insert into public.cles_examen (module_id, question, reponse, explication) values
('n3m1', 10, 'Jésus a pris notre place et porté notre péché', '« Celui qui n’a point connu le péché, il l’a fait devenir péché pour nous, afin que nous devenions en lui justice de Dieu » (2 Corinthiens 5.21).'),
('n3m1', 11, 'Le publicain', 'Jésus conclut : « celui-ci [le publicain] descendit dans sa maison justifié, plutôt que l’autre » (Luc 18.14).'),
('n3m1', 12, 'Avec son propre sang', 'Christ est entré « une fois pour toutes dans le lieu très saint, non avec le sang des boucs et des veaux, mais avec son propre sang » (Hébreux 9.12).'),
('n3m1', 13, 'Selon sa miséricorde', '« Il nous a sauvés, non à cause des œuvres de justice que nous aurions faites, mais selon sa miséricorde » (Tite 3.5).'),
('n3m1', 14, 'Vrai', 'Romains 8.30 relie appel, justification et glorification en une chaîne que rien ne brise : « ceux qu’il a justifiés, il les a aussi glorifiés ».'),
('n3m1', 15, 'Les portes du séjour des morts', '« Je bâtirai mon Église, et les portes du séjour des morts ne prévaudront point contre elle » (Matthieu 16.18).'),
('n3m1', 16, 'Une assemblée de personnes convoquées', 'L’ekklēsia est l’assemblée de ceux que Dieu appelle ; l’Église est un peuple avant d’être un lieu.'),
('n3m1', 17, 'Il est triste, mais pas comme ceux qui n’ont point d’espérance', 'Paul écrit « afin que vous ne vous affligiez pas comme les autres qui n’ont point d’espérance » : le chrétien pleure, mais avec espérance.'),
('n3m1', 18, '« Je suis la résurrection et la vie »', '« Je suis la résurrection et la vie. Celui qui croit en moi vivra, quand même il serait mort » (Jean 11.25).'),
('n3m1', 19, 'Un nouveau ciel et une nouvelle terre où Dieu habite avec les hommes', 'Jean voit « un nouveau ciel et une nouvelle terre » et entend : « Voici le tabernacle de Dieu avec les hommes ! » (Apocalypse 21.1-3).'),
('n3m1', 20, 'Il descend comme une colombe et vient sur Jésus', '« Il vit l’Esprit de Dieu descendre comme une colombe et venir sur lui » (Matthieu 3.16). Les langues de feu et le vent sont ceux de la Pentecôte (Actes 2.2-3).'),
('n3m1', 21, 'Celui qu’on appelle à ses côtés : avocat, défenseur, réconfort', 'Le paraklētos est appelé à côté de quelqu’un pour l’assister : l’Esprit est « un autre consolateur », comme Jésus l’a été pour ses disciples (Jean 14.16).'),
('n3m1', 22, 'Actes 5.3-4', 'Pierre dit à Ananias qu’il a menti au Saint-Esprit, puis : « Ce n’est pas à des hommes que tu as menti, mais à Dieu » (Actes 5.3-4).'),
('n3m1', 23, 'Glorifier le Fils en prenant de ce qui est à lui', '« Il me glorifiera, parce qu’il prendra de ce qui est à moi, et vous l’annoncera » (Jean 16.14).'),
('n3m1', 24, 'Soufflée par Dieu', 'Theopneustos signifie « soufflée par Dieu » : « Toute Écriture est inspirée de Dieu » (2 Timothée 3.16).'),
('n3m1', 25, 'Par des hommes poussés par le Saint-Esprit, qui ont parlé de la part de Dieu', '« Ce n’est pas par une volonté d’homme… mais c’est poussés par le Saint-Esprit que des hommes ont parlé de la part de Dieu » (2 Pierre 1.21).'),
('n3m1', 26, 'Matthieu 3.16-17, où les trois sont présents en même temps', 'Au baptême, le Fils sort de l’eau, l’Esprit descend sur lui et le Père parle du ciel, au même moment : ce sont trois personnes distinctes.'),
('n3m1', 27, 'À enseigner, convaincre, corriger et instruire dans la justice', 'L’Écriture est « utile pour enseigner, pour convaincre, pour corriger, pour instruire dans la justice, afin que l’homme de Dieu soit accompli » (2 Timothée 3.16-17).'),
('n3m1', 28, 'La grâce surabonde', '« Là où le péché a abondé, la grâce a surabondé » (Romains 5.20).'),
('n3m1', 29, 'Les prémices de ceux qui sont morts', '« Christ est ressuscité des morts, il est les prémices de ceux qui sont morts » (1 Corinthiens 15.20) : sa résurrection garantit la nôtre.'),
('n3m2', 0, 'Un texte hors contexte peut dire le contraire de son sens', 'Un texte sans contexte devient un prétexte : le diable lui-même a cité le Psaume 91 en le détournant (Matthieu 4.6).'),
('n3m2', 1, 'Le Psaume 91', 'Le diable cite le Psaume 91.11-12 en omettant « dans toutes tes voies » et en le transformant en invitation à tenter Dieu.'),
('n3m2', 2, '« Il est aussi écrit : Tu ne tenteras point le Seigneur, ton Dieu »', 'Jésus interprète l’Écriture par l’Écriture en citant Deutéronome 6.16.'),
('n3m2', 3, 'Ils examinaient chaque jour les Écritures pour vérifier ce qu’on leur disait', 'Ils reçurent la parole avec empressement et examinaient chaque jour les Écritures « pour voir si ce qu’on leur disait était exact ».'),
('n3m2', 4, 'Ils en donnaient le sens pour faire comprendre ce qui était lu', '« Ils en donnaient le sens pour faire comprendre ce qu’ils avaient lu » (Néhémie 8.8).'),
('n3m2', 5, 'Couper droit, tracer un chemin droit', 'Orthotomeō signifie couper droit : l’interprète fidèle trace un chemin droit à travers le texte.'),
('n3m2', 6, 'D’apprendre le contentement dans l’abondance comme dans la disette', 'Les versets 11-12 parlent de savoir vivre dans l’humiliation et dans l’abondance : Christ fortifie Paul dans toutes les situations.'),
('n3m2', 7, 'Aux exilés de Babylone, qui devaient y rester soixante-dix ans', 'Le verset suit l’annonce que l’exil durera soixante-dix ans (Jérémie 29.10) : la promesse inclut une longue attente.'),
('n3m2', 8, 'Comme une affaire réelle à juger', 'David s’indigne et condamne le riche, jusqu’à ce que Nathan lui dise : « Tu es cet homme-là ! » (2 Samuel 12.7).'),
('n3m2', 9, 'Des principes généraux de sagesse', 'Un māshāl est une maxime de sagesse qui dit ce qui arrive généralement ; Proverbes 26.4-5 montre qu’il faut discerner quand l’appliquer.'),
('n3m2', 10, 'Que la sagesse consiste à discerner quelle maxime s’applique à chaque situation', 'Les proverbes ne sont pas des règles mécaniques : parfois il faut se taire, parfois répondre, selon la situation.'),
('n3m2', 11, 'Le parallélisme des idées d’une ligne à l’autre', 'La poésie hébraïque reprend, prolonge ou oppose une idée dans la ligne suivante : « Il me fait reposer… Il me dirige… ».'),
('n3m2', 12, 'Les sept Églises', '« Les sept étoiles sont les anges des sept Églises, et les sept chandeliers sont les sept Églises » (Apocalypse 1.20).'),
('n3m2', 13, 'Faux', 'Faux. La Bible raconte par exemple l’adultère de David, mais précise : « Ce que David avait fait déplut à l’Éternel » (2 Samuel 11.27).'),
('n3m2', 14, 'Par Moïse et par tous les prophètes', '« Et, commençant par Moïse et par tous les prophètes, il leur expliqua dans toutes les Écritures ce qui le concernait » (Luc 24.27).'),
('n3m2', 15, 'De Jésus-Christ', '« Vous sondez les Écritures… ce sont elles qui rendent témoignage de moi » (Jean 5.39).'),
('n3m2', 16, 'Sens premier, principe intemporel, application', 'Hier, toujours, aujourd’hui : ce que le texte signifiait, le principe qui demeure, puis son application à notre vie.'),
('n3m2', 17, 'Qu’on utilise les passages clairs pour éclairer les passages difficiles', 'Puisque toute l’Écriture vient du même Dieu, on éclaire les textes obscurs par les textes clairs, sans bâtir de doctrine sur un verset isolé.'),
('n3m2', 18, 'Prendre des mesures pour protéger la sécurité des autres, par exemple autour d’une piscine ou sur un chantier', 'Le principe : je suis responsable de la sécurité de ceux qui sont affectés par mes biens et mes actes, par amour du prochain.'),
('n3m2', 19, 'À un homme qui se regarde dans un miroir puis oublie son visage', 'Jacques compare l’auditeur oublieux à un homme qui se regarde dans un miroir et oublie aussitôt quel il était (Jacques 1.23-24).'),
('n3m2', 20, '« Où est l’agneau pour l’holocauste ? »', '« Voici le feu et le bois ; mais où est l’agneau pour l’holocauste ? » Abraham répond : « Dieu se pourvoira lui-même de l’agneau » (Genèse 22.7-8).'),
('n3m2', 21, 'Que Dieu est puissant, même pour ressusciter les morts', '« Il pensait que Dieu est puissant, même pour ressusciter les morts ; aussi le recouvra-t-il par une sorte de résurrection » (Hébreux 11.19).'),
('n3m2', 22, 'L’Éternel pourvoira', 'Abraham appelle le lieu « Jehova-Jiré », l’Éternel voit, c’est-à-dire pourvoit (Genèse 22.14).'),
('n3m2', 23, 'La maison de l’Éternel, le temple', '« Salomon commença à bâtir la maison de l’Éternel à Jérusalem, sur la montagne de Morija » (2 Chroniques 3.1).'),
('n3m2', 24, 'Une empreinte, un modèle : un événement réel qui en préfigure un autre', 'Typos signifie empreinte, modèle : « ces choses leur sont arrivées pour servir d’exemples » (1 Corinthiens 10.11).'),
('n3m2', 25, 'Une ombre des biens à venir', '« La loi, qui possède une ombre des biens à venir, et non l’exacte représentation des choses… » (Hébreux 10.1).'),
('n3m2', 26, 'C’est une allégorie qui ne repose ni sur le texte ni sur un lien établi par l’Écriture', 'Une lecture fidèle part du sens premier et des liens que l’Écriture établit elle-même ; aucun texte ne fonde ce symbolisme.'),
('n3m2', 27, 'La bonne nouvelle que les nations seraient bénies en lui', '« L’Écriture, prévoyant que Dieu justifierait les païens par la foi, a d’avance annoncé cette bonne nouvelle à Abraham : Toutes les nations seront bénies en toi ! » (Galates 3.8).'),
('n3m2', 28, 'Ils reçurent la parole avec empressement et examinèrent chaque jour les Écritures', '« Ils reçurent la parole avec beaucoup d’empressement, et ils examinaient chaque jour les Écritures, pour voir si ce qu’on leur disait était exact » (Actes 17.11).'),
('n3m2', 29, 'Parce qu’elle s’exprime par images et parallélismes, et non par raisonnement suivi', 'Le genre littéraire commande la lecture : la poésie hébraïque procède par images et parallélismes, l’épître par argumentation.'),
('n3m3', 0, 'Faire de toutes les nations des disciples', '« Allez, faites de toutes les nations des disciples, les baptisant… et enseignez-leur à observer tout ce que je vous ai prescrit » (Matthieu 28.19-20).'),
('n3m3', 1, 'Sur l’autorité de Jésus, à qui tout pouvoir a été donné dans le ciel et sur la terre', '« Tout pouvoir m’a été donné dans le ciel et sur la terre. Allez… » : la mission découle de l’autorité de Christ.'),
('n3m3', 2, '« Je suis avec vous tous les jours, jusqu’à la fin du monde »', 'Matthieu termine son Évangile par la présence de Jésus avec ses disciples, comme il l’avait commencé avec « Emmanuel, Dieu avec nous ».'),
('n3m3', 3, 'Tous les disciples', 'Jésus dit à tous ses disciples : « vous serez mes témoins » (Actes 1.8) ; dans les Actes, les croyants dispersés annonçaient la parole partout (Actes 8.4).'),
('n3m3', 4, 'La puissance du Saint-Esprit survenant sur eux', '« Vous recevrez une puissance, le Saint-Esprit survenant sur vous, et vous serez mes témoins » (Actes 1.8).'),
('n3m3', 5, 'Jérusalem, la Judée, la Samarie, les extrémités de la terre', '« À Jérusalem, dans toute la Judée, dans la Samarie, et jusqu’aux extrémités de la terre » : un plan qui structure tout le livre des Actes.'),
('n3m3', 6, 'Dans sa maison, vers les siens, pour raconter ce que le Seigneur a fait', '« Va dans ta maison, vers les tiens, et raconte-leur tout ce que le Seigneur t’a fait, et comment il a eu pitié de toi » (Marc 5.19).'),
('n3m3', 7, 'Ils ne le peuvent pas : il faut que quelqu’un prêche', 'Paul établit une chaîne : être envoyé, prêcher, entendre, croire, invoquer. « Comment en entendront-ils parler, s’il n’y a personne qui prêche ? »'),
('n3m3', 8, 'Celui qui atteste ce qu’il a vu et vécu', 'Le témoin raconte ce qu’il a vu ; le mot a aussi donné « martyr », pour ceux qui ont scellé leur témoignage de leur vie.'),
('n3m3', 9, 'Christ est mort pour nos péchés, a été enseveli et est ressuscité le troisième jour', '« Christ est mort pour nos péchés, selon les Écritures ; il a été enseveli, et il est ressuscité le troisième jour, selon les Écritures. »'),
('n3m3', 10, 'Avec douceur et respect', '« Étant toujours prêts à vous défendre, avec douceur et respect, devant quiconque vous demande raison de l’espérance qui est en vous. »'),
('n3m3', 11, 'Une plaidoirie, une défense raisonnée', 'Apologia est la défense présentée au tribunal ; il a donné « apologétique », l’explication raisonnée de la foi.'),
('n3m3', 12, 'En lui demandant à boire', '« Donne-moi à boire » (Jean 4.7) : Jésus prend l’initiative, franchit les barrières et part d’un besoin concret.'),
('n3m3', 13, '« Venez voir un homme qui m’a dit tout ce que j’ai fait ; ne serait-ce point le Christ ? »', 'Elle laisse sa cruche et invite toute la ville à venir voir Jésus (Jean 4.28-29) ; beaucoup crurent.'),
('n3m3', 14, 'Amour de Dieu, péché, croix, réponse de foi', 'Dieu nous aime (Jean 3.16), le péché nous sépare de lui (Romains 3.23), Jésus est mort et ressuscité (1 Corinthiens 15.3-4), il faut se repentir et croire (Marc 1.15).'),
('n3m3', 15, 'Le prophète Ésaïe', 'Il lisait Ésaïe 53 (Actes 8.28-33), et Philippe, « commençant par ce passage, lui annonça la bonne nouvelle de Jésus ».'),
('n3m3', 16, '« Comment le pourrais-je, si quelqu’un ne me guide ? »', 'Il reconnaît humblement son besoin d’un guide et invite Philippe à monter et à s’asseoir avec lui.'),
('n3m3', 17, 'Faux', 'Faux. Le grand mandat demande de faire des disciples en les baptisant et en leur enseignant à obéir ; il faut accompagner, enseigner et intégrer dans l’Église.'),
('n3m3', 18, 'À une nourrice qui prend un tendre soin de ses enfants', 'Paul a été doux comme une nourrice, donnant non seulement l’Évangile mais sa propre vie, tant les Thessaloniciens lui étaient chers.'),
('n3m3', 19, 'À des hommes fidèles, capables de l’enseigner aussi à d’autres', '« Confie-le à des hommes fidèles, qui soient capables de l’enseigner aussi à d’autres » : gagner, affermir, envoyer.'),
('n3m3', 20, 'Une irritation intérieure à la vue de cette ville pleine d’idoles', '« Il sentait au-dedans de lui son esprit s’irriter, à la vue de cette ville pleine d’idoles » (Actes 17.16).'),
('n3m3', 21, 'Un autel portant l’inscription « A un dieu inconnu »', '« J’ai même découvert un autel avec cette inscription : A un dieu inconnu ! Ce que vous révérez sans le connaître, c’est ce que je vous annonce » (Actes 17.23).'),
('n3m3', 22, 'Des épicuriens et des stoïciens', '« Quelques philosophes épicuriens et stoïciens se mirent à parler avec lui » (Actes 17.18).'),
('n3m3', 23, 'La résurrection de l’homme qu’il a désigné', 'Dieu a fixé un jour pour juger le monde « par l’homme qu’il a désigné, ce dont il a donné à tous une preuve certaine en le ressuscitant des morts » (Actes 17.31).'),
('n3m3', 24, 'Certains se moquèrent, d’autres voulurent l’entendre une autre fois, quelques-uns crurent', 'Les uns se moquèrent, d’autres dirent « Nous t’entendrons là-dessus une autre fois », et quelques-uns crurent, dont Denys et Damaris.'),
('n3m3', 25, 'Adapter sa manière d’agir tout en restant sous la loi de Christ', 'Paul n’est « point sans la loi de Dieu, étant sous la loi de Christ » ; il se fait tout à tous « afin d’en sauver de toute manière quelques-uns ».'),
('n3m3', 26, 'Changer de pensée et de direction', 'Se repentir, c’est changer de pensée et de direction : se détourner des idoles vers le Dieu vivant.'),
('n3m3', 27, 'Affirmer avec respect que Jésus est le seul chemin, en l’écoutant et en l’invitant à lire les paroles de Jésus', 'L’unicité de Christ (Jean 14.6 ; Actes 4.12) se dit avec grâce et respect (Colossiens 4.6 ; 2 Timothée 2.24-25).'),
('n3m3', 28, 'De ce qu’on entend, et ce qu’on entend vient de la parole de Christ', '« Ainsi la foi vient de ce qu’on entend, et ce qu’on entend vient de la parole de Christ » (Romains 10.17).'),
('n3m3', 29, 'De lui donner à boire', '« Donne-moi à boire » (Jean 4.7) : Jésus commence par une demande simple qui ouvre la conversation.'),
('n3m4', 0, 'Contre les dominations, les autorités et les esprits méchants dans les lieux célestes', 'Éphésiens 6.12 : nous n’avons pas à lutter contre la chair et le sang, mais contre des puissances spirituelles.'),
('n3m4', 1, 'Calomniateur, accusateur', 'Diabolos signifie calomniateur ou accusateur ; Apocalypse 12.10 l’appelle l’accusateur de nos frères.'),
('n3m4', 2, 'Il ne peut agir contre Job que dans les limites fixées par Dieu', 'Job 1.12 et 2.6 : Dieu fixe des limites (« ne porte pas la main sur lui », « épargne sa vie »).'),
('n3m4', 3, 'La sobriété, la vigilance et la résistance avec une foi ferme', 'Pierre dit : « Soyez sobres, veillez… Résistez-lui avec une foi ferme ».'),
('n3m4', 4, 'Pour dérober, égorger et détruire', 'Jean 10.10 : le voleur ne vient que pour dérober, égorger et détruire ; Jésus vient donner la vie en abondance.'),
('n3m4', 5, 'Des méthodes, des stratégies habiles', 'Methodeia désigne des plans et des stratégies ; l’ennemi agit souvent par la ruse.'),
('n3m4', 6, 'L’épée de l’Esprit', 'Éphésiens 6.17 : « l’épée de l’Esprit, qui est la parole de Dieu ».'),
('n3m4', 7, 'Le bouclier de la foi', 'Éphésiens 6.16 : le bouclier de la foi permet d’éteindre tous les traits enflammés du malin.'),
('n3m4', 8, 'En citant l’Écriture : « Il est écrit »', 'À chaque tentation, Jésus répond « Il est écrit » en citant le Deutéronome.'),
('n3m4', 9, 'Se soumettre à Dieu', 'Jacques 4.7 : « Soumettez-vous donc à Dieu ; résistez au diable, et il fuira loin de vous ».'),
('n3m4', 10, 'Des raisonnements et toute hauteur qui s’élève contre la connaissance de Dieu', 'Paul parle de renverser les raisonnements et d’amener toute pensée captive à l’obéissance de Christ.'),
('n3m4', 11, 'Elle donne accès au diable', 'Paul dit : que le soleil ne se couche pas sur votre colère, et ne donnez pas accès au diable.'),
('n3m4', 12, 'Par la croix', 'Colossiens 2.15 : il les a livrées publiquement en spectacle, en triomphant d’elles par la croix.'),
('n3m4', 13, 'L’acte dont les ordonnances nous condamnaient', 'Colossiens 2.14 : il a effacé l’acte qui nous condamnait et l’a détruit en le clouant à la croix.'),
('n3m4', 14, 'Par le sang de l’Agneau, la parole de leur témoignage et le refus de craindre la mort', 'Apocalypse 12.11 : ils l’ont vaincu à cause du sang de l’agneau et de la parole de leur témoignage, et n’ont pas aimé leur vie jusqu’à craindre la mort.'),
('n3m4', 15, 'De ce que leurs noms sont écrits dans les cieux', 'Jésus dit : ne vous réjouissez pas de ce que les esprits vous sont soumis, mais de ce que vos noms sont écrits dans les cieux.'),
('n3m4', 16, 'Que l’autorité spirituelle vient d’une relation avec Christ, non d’une formule', 'L’esprit répondit : « Je connais Jésus, et je sais qui est Paul ; mais vous, qui êtes-vous ? »'),
('n3m4', 17, 'Assis, vêtu et dans son bon sens', 'Marc 5.15 : les gens le trouvèrent assis, vêtu, et dans son bon sens ; Jésus l’envoya témoigner aux siens.'),
('n3m4', 18, 'Faux', 'Faux. La Bible parle aussi de la chair, du monde, de nos choix et de la vie dans un monde déchu ; il faut être sobre (1 Pierre 5.8).'),
('n3m4', 19, 'Vrai', 'Vrai. Par sa mort, il a anéanti celui qui avait la puissance de la mort et délivré ceux qui étaient retenus par cette crainte.'),
('n3m4', 20, 'Elle ne cessait d’adresser pour lui des prières à Dieu', '« Pierre donc était gardé dans la prison ; et l’Église ne cessait d’adresser pour lui des prières à Dieu » (Actes 12.5).'),
('n3m4', 21, 'Ils lui dirent : « Tu es folle », puis « C’est son ange »', '« Ils lui dirent : Tu es folle… Et ils dirent : C’est son ange » (Actes 12.15) : ils avaient du mal à croire à l’exaucement.'),
('n3m4', 22, 'Parce qu’il n’avait pas donné gloire à Dieu', '« Un ange du Seigneur le frappa, parce qu’il n’avait pas donné gloire à Dieu » (Actes 12.23).'),
('n3m4', 23, 'Amalek était le plus fort', '« Lorsque Moïse élevait sa main, Israël était le plus fort ; et lorsqu’il baissait sa main, Amalek était le plus fort » (Exode 17.11).'),
('n3m4', 24, 'Un homme qui se tienne à la brèche devant lui en faveur du pays', '« Je cherche parmi eux un homme qui élève un mur, qui se tienne à la brèche devant moi en faveur du pays… mais je n’en trouve point » (Ézéchiel 22.30).'),
('n3m4', 25, 'Pour qu’il fasse connaître hardiment et librement le mystère de l’Évangile', '« Priez pour moi, afin qu’il me soit donné, quand j’ouvre la bouche, de faire connaître hardiment et librement le mystère de l’Évangile » (Éphésiens 6.19).'),
('n3m4', 26, 'Dans le secret, en se parfumant la tête et en se lavant le visage', '« Quand tu jeûnes, parfume ta tête et lave ton visage, afin de ne pas montrer aux hommes que tu jeûnes, mais à ton Père qui est là dans le lieu secret » (Matthieu 6.17-18).'),
('n3m4', 27, 'Détacher les chaînes de la méchanceté et renvoyer libres les opprimés', '« Voici le jeûne auquel je prends plaisir : Détache les chaînes de la méchanceté, Dénoue les liens de la servitude, Renvoie libres les opprimés » (Ésaïe 58.6).'),
('n3m4', 28, 'Avec une foi ferme, sachant que les frères dans le monde subissent les mêmes souffrances', '« Résistez-lui avec une foi ferme, sachant que les mêmes souffrances sont imposées à vos frères dans le monde » (1 Pierre 5.9).'),
('n3m4', 29, 'Il les accusait devant Dieu jour et nuit', '« Il a été précipité, l’accusateur de nos frères, celui qui les accusait devant notre Dieu jour et nuit » (Apocalypse 12.10).'),
('n3m5', 0, 'Pour servir et donner sa vie comme la rançon de plusieurs', 'Marc 10.45 : le Fils de l’homme est venu non pour être servi, mais pour servir et donner sa vie comme la rançon de plusieurs.'),
('n3m5', 1, 'Être assis à sa droite et à sa gauche dans sa gloire', 'Marc 10.37 : ils demandent d’être assis l’un à sa droite et l’autre à sa gauche dans sa gloire.'),
('n3m5', 2, 'L’esclave de tous', 'Jésus dit : quiconque veut être le premier parmi vous, qu’il soit l’esclave de tous.'),
('n3m5', 3, 'Le prix payé pour libérer un captif', 'Lytron, la rançon, désignait le prix payé pour libérer un esclave ou un prisonnier.'),
('n3m5', 4, 'Il refuse : « Non, jamais tu ne me laveras les pieds »', 'Jean 13.8 : Pierre dit « Non, jamais tu ne me laveras les pieds ».'),
('n3m5', 5, 'De se laver les pieds les uns aux autres, car il leur a donné un exemple', 'Jésus dit : vous devez aussi vous laver les pieds les uns aux autres ; car je vous ai donné un exemple.'),
('n3m5', 6, 'Regarder les autres comme étant au-dessus de soi-même', 'Philippiens 2.3 : que l’humilité vous fasse regarder les autres comme étant au-dessus de vous-mêmes.'),
('n3m5', 7, 'En prenant une forme de serviteur et en devenant semblable aux hommes', 'Il s’est dépouillé lui-même en prenant une forme de serviteur, en devenant semblable aux hommes, sans cesser d’être Dieu.'),
('n3m5', 8, 'Les veuves des Hellénistes étaient négligées dans la distribution quotidienne', 'Actes 6.1 : les Hellénistes murmuraient parce que leurs veuves étaient négligées dans la distribution quotidienne.'),
('n3m5', 9, 'Avoir un bon témoignage, être pleins d’Esprit-Saint et de sagesse', 'Actes 6.3 : des hommes de qui l’on rende un bon témoignage, pleins d’Esprit-Saint et de sagesse.'),
('n3m5', 10, 'La parole de Dieu se répandait et le nombre des disciples augmentait beaucoup', 'Actes 6.7 : la parole de Dieu se répandait de plus en plus et le nombre des disciples augmentait beaucoup à Jérusalem.'),
('n3m5', 11, 'Pour le perfectionnement des saints en vue de l’œuvre du ministère', 'Éphésiens 4.12 : pour le perfectionnement des saints en vue de l’œuvre du ministère et de l’édification du corps de Christ.'),
('n3m5', 12, 'Mettre en état, équiper, préparer à remplir sa fonction', 'Katartismos évoque la remise en état et l’équipement, comme pour réparer des filets de pêche.'),
('n3m5', 13, 'Un corps avec plusieurs membres', 'Romains 12.4-5 : comme nous avons plusieurs membres dans un seul corps, nous formons un seul corps en Christ.'),
('n3m5', 14, 'D’être trouvés fidèles', '1 Corinthiens 4.2 : ce qu’on demande des dispensateurs, c’est que chacun soit trouvé fidèle.'),
('n3m5', 15, 'Si nous ne nous relâchons pas', 'Galates 6.9 : nous moissonnerons au temps convenable, si nous ne nous relâchons pas.'),
('n3m5', 16, 'Il lui a donné à manger et l’a laissé dormir', '1 Rois 19.5-7 : un ange le toucha et lui dit « Lève-toi, mange », et il se recoucha ; Dieu prit soin de son corps.'),
('n3m5', 17, 'Parce qu’il avait enterré son talent par peur et paresse', 'Il n’est pas blâmé d’avoir peu reçu, mais d’avoir caché son talent au lieu de le faire fructifier.'),
('n3m5', 18, 'Faux', 'Faux. En Actes 6, servir aux tables est un vrai ministère, et 1 Corinthiens 12.22 dit que les membres qui paraissent les plus faibles sont nécessaires.'),
('n3m5', 19, 'Vrai', 'Vrai. Paul dit : sachant que votre travail ne sera pas vain dans le Seigneur.'),
('n3m5', 20, 'Elle faisait beaucoup de bonnes œuvres et d’aumônes', '« Elle faisait beaucoup de bonnes œuvres et d’aumônes » (Actes 9.36).'),
('n3m5', 21, 'Les tuniques et les vêtements que faisait Dorcas', '« Toutes les veuves l’entourèrent en pleurant, et lui montrèrent les tuniques et les vêtements que faisait Dorcas pendant qu’elle était avec elles » (Actes 9.39).'),
('n3m5', 22, 'Il fit sortir tout le monde, se mit à genoux et pria', '« Pierre fit sortir tout le monde, se mit à genoux, et pria ; puis, se tournant vers le corps, il dit : Tabitha, lève-toi ! » (Actes 9.40).'),
('n3m5', 23, 'Chez un corroyeur nommé Simon', '« Pierre demeura quelque temps à Joppé, chez un corroyeur nommé Simon » (Actes 9.43).'),
('n3m5', 24, 'Amour de l’étranger', 'Philoxenia signifie littéralement « amour de l’étranger » (Romains 12.13 ; Hébreux 13.2).'),
('n3m5', 25, 'Parce qu’en l’exerçant, quelques-uns ont logé des anges sans le savoir', '« N’oubliez pas l’hospitalité ; car, en l’exerçant, quelques-uns ont logé des anges, sans le savoir » (Hébreux 13.2).'),
('n3m5', 26, 'Nous sommes créés en Jésus-Christ pour de bonnes œuvres que Dieu a préparées d’avance', '« Nous sommes son ouvrage, ayant été créés en Jésus-Christ pour de bonnes œuvres, que Dieu a préparées d’avance, afin que nous les pratiquions » (Éphésiens 2.10).'),
('n3m5', 27, 'Qu’elle est diaconesse de l’Église de Cenchrées et a donné aide à plusieurs', '« Phœbé, notre sœur, qui est diaconesse de l’Église de Cenchrées… car elle a donné aide à plusieurs et à moi-même » (Romains 16.1-2).'),
('n3m5', 28, 'Elles se sont d’abord données elles-mêmes au Seigneur', '« Ils se sont d’abord donnés eux-mêmes au Seigneur, puis à nous, par la volonté de Dieu » (2 Corinthiens 8.5).'),
('n3m5', 29, 'Comme nécessaires', '« Les membres du corps qui paraissent être les plus faibles sont nécessaires » (1 Corinthiens 12.22).'),
('n3m6', 0, 'Le sel de la terre et la lumière du monde', 'Matthieu 5.13-14 : « Vous êtes le sel de la terre… Vous êtes la lumière du monde. »'),
('n3m6', 1, 'Afin que les hommes voient leurs bonnes œuvres et glorifient le Père', 'Le but est que les hommes glorifient notre Père qui est dans les cieux.'),
('n3m6', 2, 'Paix et bien-être complet, prospérité, harmonie', 'Shalom désigne la paix au sens large : bien-être, prospérité, harmonie ; Dieu demande de rechercher le bien de la ville.'),
('n3m6', 3, 'Rechercher le bien de la ville et prier l’Éternel en sa faveur', 'Jérémie 29.7 : recherchez le bien de la ville… et priez l’Éternel en sa faveur, parce que votre bonheur dépend du sien.'),
('n3m6', 4, 'De ne pas se souiller par les mets et le vin du roi', 'Daniel 1.8 : Daniel résolut de ne pas se souiller par les mets du roi et par le vin dont le roi buvait.'),
('n3m6', 5, 'Par une demande respectueuse et la proposition d’un essai de dix jours', 'Daniel demanda poliment et proposa un essai de dix jours avec des légumes et de l’eau.'),
('n3m6', 6, 'Devenir fade, et aussi devenir fou ou insensé', 'Môrainô signifie devenir fade et aussi devenir insensé : un disciple sans différence perd sa raison d’être.'),
('n3m6', 7, 'Pratiquer la justice, aimer la miséricorde et marcher humblement avec Dieu', 'Michée 6.8 : que tu pratiques la justice, que tu aimes la miséricorde, et que tu marches humblement avec ton Dieu.'),
('n3m6', 8, 'L’amour fidèle et loyal de l’alliance', 'Hesed, traduit par « miséricorde », est la bonté fidèle et loyale de l’alliance.'),
('n3m6', 9, 'De Dieu, qui les a instituées', 'Romains 13.1 : il n’y a point d’autorité qui ne vienne de Dieu, et les autorités qui existent ont été instituées de Dieu.'),
('n3m6', 10, 'Rendre à tous ce qui leur est dû : l’impôt, le tribut, la crainte, l’honneur', 'Romains 13.7 : rendez à tous ce qui leur est dû : l’impôt à qui vous devez l’impôt…'),
('n3m6', 11, 'Quand l’autorité humaine ordonne clairement de désobéir à Dieu', 'Les apôtres désobéissent à l’ordre de ne plus enseigner au nom de Jésus, car il contredisait le commandement de Dieu.'),
('n3m6', 12, 'Ils se sont retirés joyeux d’avoir été jugés dignes de subir des outrages pour le nom de Jésus', 'Actes 5.41 : ils se retirèrent joyeux ; leur désobéissance était respectueuse et non violente.'),
('n3m6', 13, 'Qu’il donnerait aux pauvres la moitié de ses biens et rendrait le quadruple à ceux qu’il avait lésés', 'Luc 19.8 : je donne aux pauvres la moitié de mes biens, et si j’ai fait tort à quelqu’un, je lui rends le quadruple.'),
('n3m6', 14, 'La balance fausse', 'Proverbes 11.1 : la balance fausse est en horreur à l’Éternel, mais le poids juste lui est agréable.'),
('n3m6', 15, 'Le Samaritain', 'Le docteur de la loi répond : celui qui a exercé la miséricorde envers lui ; c’est le Samaritain.'),
('n3m6', 16, 'Au Roi lui-même', 'Matthieu 25.40 : c’est à moi que vous les avez faites.'),
('n3m6', 17, 'Morte en elle-même', 'Jacques 2.17 : si elle n’a pas les œuvres, elle est morte en elle-même.'),
('n3m6', 18, 'Faux', 'Faux. Exode 23.8 interdit les présents qui corrompent, et Proverbes 11.1 condamne la balance fausse, quelle que soit la norme sociale.'),
('n3m6', 19, 'Vrai', 'Vrai. Galates 6.10 : pratiquons le bien envers tous, et surtout envers les frères en la foi.'),
('n3m6', 20, 'Pour pourvoir à leur nourriture en utilisant le droit des pauvres et des étrangers', 'Veuve, pauvre et étrangère, Ruth utilise le droit de glanage prévu par la loi (Lévitique 19.9-10 ; Ruth 2.2).'),
('n3m6', 21, '« Que l’Éternel soit avec vous ! »', '« Boaz… dit aux moissonneurs : Que l’Éternel soit avec vous ! Ils lui répondirent : Que l’Éternel te bénisse ! » (Ruth 2.4).'),
('n3m6', 22, 'De l’Éternel, le Dieu d’Israël', '« Que ta récompense soit entière de la part de l’Éternel, le Dieu d’Israël, sous les ailes duquel tu es venue te réfugier ! » (Ruth 2.12).'),
('n3m6', 23, 'Un proche parent qui a droit et devoir de rachat', 'Le gō’ēl est le proche parent qui rachète la terre ou relève le nom d’un parent appauvri (Lévitique 25.25 ; Ruth 4.1-10).'),
('n3m6', 24, 'Sans le retenir jusqu’au lendemain', '« Tu ne retiendras point jusqu’au lendemain le salaire du mercenaire » (Lévitique 19.13).'),
('n3m6', 25, 'Il crie, et les cris des moissonneurs parviennent aux oreilles du Seigneur', '« Le salaire des ouvriers… dont vous les avez frustrés, crie, et les cris des moissonneurs sont parvenus jusqu’aux oreilles du Seigneur des armées » (Jacques 5.4).'),
('n3m6', 26, 'Pour avoir de quoi donner à celui qui est dans le besoin', '« Qu’il travaille, en faisant de ses mains ce qui est bien, pour avoir de quoi donner à celui qui est dans le besoin » (Éphésiens 4.28).'),
('n3m6', 27, 'Outrager celui qui l’a fait', '« Opprimer le pauvre, c’est outrager celui qui l’a fait ; mais avoir pitié de l’indigent, c’est l’honorer » (Proverbes 14.31).'),
('n3m6', 28, 'La paix (shalom) de la ville où il les a menés', '« Recherchez le bien de la ville où je vous ai menés en captivité, et priez l’Éternel en sa faveur, parce que votre bonheur dépend du sien » (Jérémie 29.7).'),
('n3m6', 29, '« Ton peuple sera mon peuple, et ton Dieu sera mon Dieu »', '« Où tu iras j’irai, où tu demeureras je demeurerai ; ton peuple sera mon peuple, et ton Dieu sera mon Dieu » (Ruth 1.16).'),
('n4m1', 0, 'Le caractère', 'Sur une quinzaine de qualités demandées en 1 Timothée 3.2-7, presque toutes concernent le caractère ; une seule (« propre à l’enseignement ») porte sur une compétence.'),
('n4m1', 1, 'Qu’on ne peut saisir, sur qui l’accusation n’a pas prise', 'Anepilêmptos signifie « qu’on ne peut saisir » : une vie qui ne donne pas prise à une accusation fondée, sans être une perfection sans péché.'),
('n4m1', 2, 'Au cœur', '« L’homme regarde à ce qui frappe les yeux, mais l’Éternel regarde au coeur » (1 Samuel 16.7).'),
('n4m1', 3, 'Il faisait paître les brebis', 'Isaï dit : « Il reste encore le plus jeune, mais il fait paître les brebis » (1 Samuel 16.11).'),
('n4m1', 4, 'De peur qu’enflé d’orgueil il ne tombe sous le jugement du diable', 'Paul écrit : « Il ne faut pas qu’il soit un nouveau converti, de peur qu’enflé d’orgueil il ne tombe sous le jugement du diable » (1 Timothée 3.6).'),
('n4m1', 5, 'Économe de Dieu', '« Il faut que l’évêque soit irréprochable, comme économe de Dieu » (Tite 1.7) : il gère ce qui appartient à Dieu.'),
('n4m1', 6, 'Faux', 'Faux : « Qu’on les éprouve d’abord, et qu’ils exercent ensuite leur ministère, s’ils sont sans reproche » (1 Timothée 3.10).'),
('n4m1', 7, 'Je ne vous ai jamais connus', 'Jésus dit : « Je ne vous ai jamais connus, retirez-vous de moi, vous qui commettez l’iniquité » (Matthieu 7.23). Les dons ne prouvent pas, à eux seuls, une vie juste.'),
('n4m1', 8, 'Volontairement, avec dévouement et en étant les modèles du troupeau', 'Pierre écrit : « non par contrainte, mais volontairement… non pour un gain sordide, mais avec dévouement ; non comme dominant… mais en étant les modèles du troupeau ».'),
('n4m1', 9, 'Il leur résiste', '« Dieu résiste aux orgueilleux, Mais il fait grâce aux humbles » (1 Pierre 5.5, citant Proverbes 3.34).'),
('n4m1', 10, 'Tu es cet homme-là !', '« Et Nathan dit à David : Tu es cet homme-là ! » (2 Samuel 12.7).'),
('n4m1', 11, 'Il a dit : « J’ai péché contre l’Éternel ! »', '« David dit à Nathan : J’ai péché contre l’Éternel ! » (2 Samuel 12.13). C’est Saül qui, en 1 Samuel 15.30, avait demandé à être honoré devant les anciens.'),
('n4m1', 12, 'L’orgueil', '« L’arrogance précède la ruine, Et l’orgueil précède la chute » (Proverbes 16.18).'),
('n4m1', 13, 'Le serviteur des autres', '« Quiconque veut être grand parmi vous, qu’il soit votre serviteur ; et quiconque veut être le premier parmi vous, qu’il soit l’esclave de tous » (Marc 10.43-44).'),
('n4m1', 14, 'Faire compter et vérifier les fonds par plusieurs personnes et rendre compte de façon transparente', 'Paul recherchait « ce qui est bien, non seulement devant le Seigneur, mais aussi devant les hommes » (2 Corinthiens 8.21). Des garde-fous transparents protègent le leader et l’Église.'),
('n4m1', 15, 'À eux-mêmes, puis à tout le troupeau', '« Prenez donc garde à vous-mêmes, et à tout le troupeau sur lequel le Saint-Esprit vous a établis évêques » (Actes 20.28).'),
('n4m1', 16, 'Il sortit dans un lieu désert pour prier', '« Vers le matin, pendant qu’il faisait encore très sombre, il se leva, et sortit pour aller dans un lieu désert, où il pria » (Marc 1.35).'),
('n4m1', 17, 'Il le laisse dormir et lui donne à manger et à boire', 'Un ange le touche et dit : « Lève-toi, mange, car le chemin est trop long pour toi » (1 Rois 19.5-7). Dieu prend soin du corps de son serviteur.'),
('n4m1', 18, 'Vrai', 'Vrai : « Veille sur toi-même et sur ton enseignement ; persévère dans ces choses » (1 Timothée 4.16).'),
('n4m1', 19, 'Parce qu’il était fidèle et qu’on ne trouvait chez lui ni faute ni rien de mauvais', 'Ils ne purent trouver « aucune occasion, ni aucune chose à reprendre, parce qu’il était fidèle » (Daniel 6.4). C’est une illustration vivante du mot « irréprochable ».'),
('n4m1', 20, 'De Zacharie, qui avait l’intelligence des visions de Dieu', '« Il s’appliqua à rechercher Dieu pendant la vie de Zacharie, qui avait l’intelligence des visions de Dieu ; et dans le temps où il rechercha l’Éternel, Dieu le fit prospérer » (2 Chroniques 26.5).'),
('n4m1', 21, 'Il entra dans le temple pour brûler des parfums sur l’autel des parfums', '« Il entra dans le temple de l’Éternel pour brûler des parfums sur l’autel des parfums » (2 Chroniques 26.16), un service réservé aux sacrificateurs.'),
('n4m1', 22, 'Pendant qu’il s’irritait contre les sacrificateurs qui le reprenaient', '« Comme il s’irritait contre les sacrificateurs, la lèpre éclata sur son front » (2 Chroniques 26.19).'),
('n4m1', 23, 'Rechercher, consulter, se tourner vers Dieu', 'Dāraš signifie rechercher Dieu avec dépendance ; la prospérité d’Ozias est liée à cette recherche (2 Chroniques 26.5).'),
('n4m1', 24, 'À Aaron et à ses fils, comme un pur don', '« Je vous accorde en pur don l’exercice du sacerdoce. L’étranger qui approchera sera mis à mort » (Nombres 18.7).'),
('n4m1', 25, 'Un homme qui aime à être le premier parmi eux', '« Diotrèphe, qui aime à être le premier parmi eux, ne nous reçoit point » (3 Jean 9).'),
('n4m1', 26, '« Ma grâce te suffit, car ma puissance s’accomplit dans la faiblesse »', '« Ma grâce te suffit, car ma puissance s’accomplit dans la faiblesse » (2 Corinthiens 12.9).'),
('n4m1', 27, '1 Corinthiens 10.12 : que celui qui croit être debout prenne garde de tomber', 'Le succès et l’isolement sont les terrains de l’orgueil ; Paul avertit : « que celui qui croit être debout prenne garde de tomber ! » (1 Corinthiens 10.12).'),
('n4m1', 28, 'Qu’il peut abaisser ceux qui marchent avec orgueil', '« Je loue, j’exalte et je glorifie le roi des cieux… et qui peut abaisser ceux qui marchent avec orgueil » (Daniel 4.37).'),
('n4m1', 29, 'Être arrogant', '« Il faut que l’évêque soit irréprochable, comme économe de Dieu ; qu’il ne soit ni arrogant, ni colère… » (Tite 1.7).'),
('n4m2', 0, 'Quatre', 'Paul (« de moi »), Timothée (« tu »), des hommes fidèles, et « d’autres » : quatre générations dans un seul verset (2 Timothée 2.2).'),
('n4m2', 1, 'À des hommes fidèles, capables de l’enseigner à d’autres', '« Confie-le à des hommes fidèles, qui soient capables de l’enseigner aussi à d’autres » (2 Timothée 2.2). La fidélité est le premier critère.'),
('n4m2', 2, 'Les avoir avec lui', '« Il en établit douze, pour les avoir avec lui, et pour les envoyer prêcher » (Marc 3.14). La relation précède l’envoi.'),
('n4m2', 3, 'Faites des disciples', 'Le verbe principal est mathêteusate, « faites des disciples » ; aller, baptiser et enseigner décrivent comment le faire.'),
('n4m2', 4, 'Il labourait avec des bœufs', 'Élie trouva Élisée « qui labourait », avec douze paires de bœufs devant lui (1 Rois 19.19).'),
('n4m2', 5, 'Comme celui qui versait l’eau sur les mains d’Élie', '« Il y a ici Élisée, fils de Schaphath, qui versait l’eau sur les mains d’Élie » (2 Rois 3.11). Il a été formé dans le service.'),
('n4m2', 6, 'Une double portion de son esprit', '« Qu’il y ait sur moi, je te prie, une double portion de ton esprit ! » (2 Rois 2.9).'),
('n4m2', 7, 'Faux', 'Faux : il a dit « Où est l’Éternel, le Dieu d’Élie ? » (2 Rois 2.14). La source de la puissance est Dieu, pas le mentor.'),
('n4m2', 8, 'Deux à deux', '« Il les envoya deux à deux devant lui dans toutes les villes et dans tous les lieux où lui-même devait aller » (Luc 10.1).'),
('n4m2', 9, 'De ce que leurs noms sont écrits dans les cieux', '« Ne vous réjouissez pas de ce que les esprits vous sont soumis ; mais réjouissez-vous de ce que vos noms sont écrits dans les cieux » (Luc 10.20).'),
('n4m2', 10, 'Ils racontèrent ce qu’ils avaient fait, et Jésus les prit à l’écart avec lui', '« Les apôtres, étant de retour, racontèrent à Jésus tout ce qu’ils avaient fait. Il les prit avec lui, et se retira à l’écart » (Luc 9.10). C’est un temps de débriefing.'),
('n4m2', 11, 'Leur incrédulité', '« C’est à cause de votre incrédulité, leur dit Jésus » (Matthieu 17.20). Il ajoute que cette sorte de démon ne sort que par la prière (et le jeûne).'),
('n4m2', 12, 'En particulier, quand ils l’ont interrogé', '« Alors les disciples s’approchèrent de Jésus, et lui dirent en particulier : Pourquoi n’avons-nous pu chasser ce démon ? » (Matthieu 17.19). La correction a eu lieu en privé.'),
('n4m2', 13, 'Tu fais, je t’aide', 'Les quatre étapes : je fais, tu regardes ; je fais, tu m’aides ; tu fais, je t’aide ; tu fais, je regarde.'),
('n4m2', 14, 'Tu t’épuiseras toi-même, et tu épuiseras ce peuple', '« Ce que tu fais n’est pas bien. Tu t’épuiseras toi-même, et tu épuiseras ce peuple qui est avec toi » (Exode 18.17-18).'),
('n4m2', 15, 'Capables, craignant Dieu, intègres, ennemis de la cupidité', '« Choisis parmi tout le peuple des hommes capables, craignant Dieu, des hommes intègres, ennemis de la cupidité » (Exode 18.21).'),
('n4m2', 16, 'En lui imposant les mains devant le prêtre Éléazar et toute l’assemblée', 'Moïse plaça Josué devant Éléazar et toute l’assemblée, posa les mains sur lui et lui donna ses ordres (Nombres 27.22-23).'),
('n4m2', 17, 'Fils d’exhortation', '« Joseph, surnommé par les apôtres Barnabas, ce qui signifie fils d’exhortation » (Actes 4.36).'),
('n4m2', 18, 'Vrai', 'Vrai : « Prends Marc, et amène-le avec toi, car il m’est utile pour le ministère » (2 Timothée 4.11). Celui qui avait échoué a été restauré.'),
('n4m2', 19, 'Former dès maintenant des personnes fidèles et leur confier progressivement de vraies responsabilités', 'Comme Moïse avec Josué et Paul avec Timothée (2 Timothée 2.2), le leader forme des personnes fidèles et leur confie une responsabilité réelle avec accompagnement.'),
('n4m2', 20, 'Un disciple, fils d’une femme juive fidèle et d’un père grec, dont les frères rendaient un bon témoignage', '« Il y avait là un disciple nommé Timothée, fils d’une femme juive fidèle et d’un père grec. Les frères de Lystre et d’Icone rendaient de lui un bon témoignage » (Actes 16.1-2).'),
('n4m2', 21, 'Dans son aïeule Loïs et sa mère Eunice', '« La foi sincère qui est en toi, qui habita d’abord dans ton aïeule Loïs et dans ta mère Eunice » (2 Timothée 1.5).'),
('n4m2', 22, 'Raviver un feu en soufflant sur les braises', 'Anazōpyreō signifie raviver un feu : le don de Dieu, toujours présent, doit être entretenu.'),
('n4m2', 23, 'Un esprit de force, d’amour et de sagesse', '« Ce n’est pas un esprit de timidité que Dieu nous a donné, mais un esprit de force, d’amour et de sagesse » (2 Timothée 1.7).'),
('n4m2', 24, 'Comme celui d’un enfant avec son père, au service de l’Évangile', '« Il a été mis à l’épreuve, en se consacrant au service de l’Évangile avec moi, comme un enfant avec son père » (Philippiens 2.22).'),
('n4m2', 25, 'En étant un modèle pour les fidèles en parole, en conduite, en charité, en foi, en pureté', '« Que personne ne méprise ta jeunesse ; mais sois un modèle pour les fidèles, en parole, en conduite, en charité, en foi, en pureté » (1 Timothée 4.12).'),
('n4m2', 26, 'Une génération qui ne connaissait point l’Éternel, ni ce qu’il avait fait pour Israël', '« Il s’éleva après elle une autre génération, qui ne connaissait point l’Éternel, ni ce qu’il avait fait en faveur d’Israël » (Juges 2.10).'),
('n4m2', 27, 'On peut avoir dix mille maîtres, mais pas plusieurs pères', '« Quand vous auriez dix mille maîtres en Christ, vous n’avez cependant pas plusieurs pères » (1 Corinthiens 4.15).'),
('n4m2', 28, 'L’accompagner dans son caractère et son témoignage avant de lui confier une responsabilité publique', 'Paul choisit Timothée sur la base d’un bon témoignage (Actes 16.2) ; le responsable ne doit pas être nommé trop vite (1 Timothée 3.6-7 ; 5.22).'),
('n4m2', 29, 'Parce que Moïse s’épuiserait, et le peuple aussi : la tâche était au-dessus de ses forces', '« Ce que tu fais n’est pas bien. Tu t’épuiseras toi-même, et tu épuiseras ce peuple qui est avec toi ; car la chose est au-dessus de tes forces » (Exode 18.17-18).'),
('n4m3', 0, 'La parole', '« Prêche la parole, insiste en toute occasion, favorable ou non » (2 Timothée 4.2).'),
('n4m3', 1, 'Proclamer publiquement comme un héraut', 'Kêrussô vient de kêrux, le héraut qui annonçait fidèlement le message officiel de son roi.'),
('n4m3', 2, 'Ils se donneront une foule de docteurs selon leurs propres désirs', '« Ayant la démangeaison d’entendre des choses agréables, ils se donneront une foule de docteurs selon leurs propres désirs » (2 Timothée 4.3).'),
('n4m3', 3, 'Sur la puissance de Dieu', 'Sa prédication reposait sur « une démonstration d’Esprit et de puissance, afin que votre foi fût fondée, non sur la sagesse des hommes, mais sur la puissance de Dieu ».'),
('n4m3', 4, 'Jésus-Christ, et Jésus-Christ crucifié', '« Je n’ai pas eu la pensée de savoir parmi vous autre chose que Jésus-Christ, et Jésus-Christ crucifié » (1 Corinthiens 2.2).'),
('n4m3', 5, 'Vrai', 'Vrai : « qu’il n’y ait pas parmi vous un grand nombre de personnes qui se mettent à enseigner, car vous savez que nous serons jugés plus sévèrement » (Jacques 3.1).'),
('n4m3', 6, 'Je ne sais point parler, car je suis un enfant', '« Ah ! Seigneur Éternel ! voici, je ne sais point parler, car je suis un enfant » (Jérémie 1.6).'),
('n4m3', 7, 'Il toucha sa bouche et mit ses paroles dans sa bouche', '« L’Éternel étendit sa main, et toucha ma bouche ; et l’Éternel me dit : Voici, je mets mes paroles dans ta bouche » (Jérémie 1.9).'),
('n4m3', 8, 'Comme un feu dévorant renfermé dans ses os', '« Il y a dans mon coeur comme un feu dévorant Qui est renfermé dans mes os. Je m’efforce de le contenir, et je ne le puis » (Jérémie 20.9).'),
('n4m3', 9, 'Étudier, mettre en pratique, enseigner', '« Esdras avait appliqué son coeur à étudier et à mettre en pratique la loi de l’Éternel, et à enseigner » (Esdras 7.10).'),
('n4m3', 10, 'Ils en donnaient le sens pour faire comprendre', '« Ils lisaient distinctement dans le livre de la loi de Dieu, et ils en donnaient le sens pour faire comprendre ce qu’ils avaient lu » (Néhémie 8.8).'),
('n4m3', 11, 'Parce qu’ils avaient compris les paroles qu’on leur avait expliquées', '« Car ils avaient compris les paroles qu’on leur avait expliquées » (Néhémie 8.12).'),
('n4m3', 12, 'La joie de l’Éternel', '« Ne vous affligez pas, car la joie de l’Éternel sera votre force » (Néhémie 8.10).'),
('n4m3', 13, 'Hommes frères, que ferons-nous ?', '« Ils eurent le coeur vivement touché, et ils dirent à Pierre et aux autres apôtres : Hommes frères, que ferons-nous ? » (Actes 2.37).'),
('n4m3', 14, 'Partir du texte biblique, l’étudier dans son contexte et en dégager l’idée centrale', 'Le prédicateur doit dispenser « droitement la parole de la vérité » (2 Timothée 2.15) et, comme les Lévites, donner le sens du texte (Néhémie 8.8).'),
('n4m3', 15, 'À un homme prudent qui a bâti sa maison sur le roc', '« Quiconque entend ces paroles que je dis et les met en pratique, sera semblable à un homme prudent qui a bâti sa maison sur le roc » (Matthieu 7.24).'),
('n4m3', 16, 'Il enseignait comme ayant autorité', '« Il enseignait comme ayant autorité, et non pas comme leurs scribes » (Matthieu 7.29).'),
('n4m3', 17, 'Selon que ses auditeurs étaient capables de l’entendre', '« Il leur annonçait la parole, selon qu’ils étaient capables de l’entendre » ; en particulier, il expliquait tout à ses disciples (Marc 4.33-34).'),
('n4m3', 18, 'Présenter à Dieu tout homme devenu parfait en Christ', '« Afin de présenter à Dieu tout homme, devenu parfait en Christ » (Colossiens 1.28) ; « parfait » (teleios) signifie mûr, accompli.'),
('n4m3', 19, 'Faux', 'Faux : Jésus demanda d’abord « De quoi vous entretenez-vous en marchant ? » puis « Quoi ? », et les écouta avant de leur expliquer les Écritures (Luc 24.17-27).'),
('n4m3', 20, 'Un homme éloquent, versé dans les Écritures et fervent d’esprit', '« Homme éloquent et versé dans les Écritures… fervent d’esprit, il annonçait et enseignait avec exactitude ce qui concerne Jésus » (Actes 18.24-25).'),
('n4m3', 21, 'Il ne connaissait que le baptême de Jean', '« Il annonçait et enseignait avec exactitude ce qui concerne Jésus, bien qu’il ne connût que le baptême de Jean » (Actes 18.25).'),
('n4m3', 22, 'Ils l’ont pris avec eux et lui ont exposé plus exactement la voie de Dieu', '« Aquilas et Priscille, l’ayant entendu, le prirent avec eux, et lui exposèrent plus exactement la voie de Dieu » (Actes 18.26).'),
('n4m3', 23, 'Il réfutait vivement les Juifs en public, démontrant par les Écritures que Jésus est le Christ', '« Il réfutait vivement les Juifs en public, démontrant par les Écritures que Jésus est le Christ » (Actes 18.28).'),
('n4m3', 24, 'Dieu seul', '« J’ai planté, Apollos a arrosé, mais Dieu a fait croître, en sorte que ce n’est pas celui qui plante qui est quelque chose, ni celui qui arrose, mais Dieu qui fait croître » (1 Corinthiens 3.6-7).'),
('n4m3', 25, 'Tout le conseil de Dieu, sans en rien cacher', '« Je vous ai annoncé tout le conseil de Dieu, sans en rien cacher » (Actes 20.27).'),
('n4m3', 26, 'Ils se donneront une foule de docteurs selon leurs propres désirs', '« Ayant la démangeaison d’entendre des choses agréables, ils se donneront une foule de docteurs selon leurs propres désirs » (2 Timothée 4.3).'),
('n4m3', 27, 'Sur lui-même et sur son enseignement', '« Veille sur toi-même et sur ton enseignement ; persévère dans ces choses, car, en agissant ainsi, tu te sauveras toi-même, et tu sauveras ceux qui t’écoutent » (1 Timothée 4.16).'),
('n4m3', 28, 'L’intégrité : digérer le texte soi-même et ne pas présenter comme sien le travail d’autrui', 'Paul déclare : « c’est avec sincérité, mais c’est de la part de Dieu, que nous parlons » (2 Corinthiens 2.17) et rejette « les choses honteuses qui se font en secret » (2 Corinthiens 4.2).'),
('n4m3', 29, 'Étudier la loi de l’Éternel, la mettre en pratique, puis enseigner', '« Esdras avait appliqué son cœur à étudier et à mettre en pratique la loi de l’Éternel, et à enseigner au milieu d’Israël les lois et les ordonnances » (Esdras 7.10).'),
('n4m4', 0, 'L’écrire et la graver sur des tables afin qu’on la lise couramment', 'Habacuc 2.2 : Écris la prophétie : grave-la sur des tables, afin qu’on la lise couramment.'),
('n4m4', 1, 'Il a pleuré, jeûné et prié pendant des jours', 'Néhémie 1.4 : il s’assit, pleura, fut plusieurs jours dans la désolation, jeûna et pria le Dieu des cieux.'),
('n4m4', 2, 'Pour évaluer la réalité avant de partager la vision', 'Néhémie 2.12-16 : il observe discrètement l’état des murs avant de présenter le projet ; observer précède partager.'),
('n4m4', 3, 'Levons-nous, et bâtissons !', 'Néhémie 2.18 : Ils dirent : Levons-nous, et bâtissons ! Et ils se fortifièrent dans cette bonne résolution.'),
('n4m4', 4, 'La parole révélée de Dieu', 'Châzôn désigne ce que Dieu fait voir à son prophète ; le parallèle avec la loi montre qu’il s’agit de la Parole de Dieu.'),
('n4m4', 5, 'Il s’assied pour calculer la dépense', 'Luc 14.28 : il s’assied d’abord pour calculer la dépense et voir s’il a de quoi la terminer.'),
('n4m4', 6, 'Faux', 'Jésus prend le calcul de la dépense comme exemple de sagesse (Luc 14.28) ; on planifie avec humilité en disant si Dieu le veut (Jacques 4.15).'),
('n4m4', 7, 'Il a prié et établi une garde jour et nuit', 'Néhémie 4.9 : Nous priâmes notre Dieu, et nous établîmes une garde jour et nuit ; prière et organisation vont ensemble.'),
('n4m4', 8, 'La circoncision des païens convertis pour être sauvés', 'Actes 15.1 : certains enseignaient : Si vous n’êtes circoncis selon le rite de Moïse, vous ne pouvez être sauvés.'),
('n4m4', 9, 'Amos', 'Actes 15.16-17 reprend Amos 9.11-12 : Dieu rebâtira la tente de David afin que les nations cherchent le Seigneur.'),
('n4m4', 10, 'Il a paru bon au Saint-Esprit et à nous', 'Actes 15.28 : Car il a paru bon au Saint-Esprit et à nous de ne pas vous imposer d’autre charge que ce qui est nécessaire.'),
('n4m4', 11, 'Aller le reprendre entre toi et lui seul', 'Matthieu 18.15 : va et reprends-le entre toi et lui seul. S’il t’écoute, tu as gagné ton frère.'),
('n4m4', 12, 'Gagner son frère', 'Le verbe kerdainô, gagner, montre que le but est la restauration de la relation (Matthieu 18.15).'),
('n4m4', 13, 'Il les exhorte toutes deux et demande à un collègue fidèle de les aider', 'Paul exhorte chacune à être d’un même sentiment dans le Seigneur et demande à un fidèle collègue de les aider (Philippiens 4.2-3).'),
('n4m4', 14, 'Protéger l’enfant et respecter la loi, y compris en signalant aux autorités', 'Les abus exigent de protéger la victime et de respecter la loi ; Romains 13 reconnaît le rôle des autorités et Matthieu 18.6 montre la gravité de scandaliser un petit.'),
('n4m4', 15, 'Tu t’épuiseras toi-même, et tu épuiseras ce peuple', 'Exode 18.18 : Tu t’épuiseras toi-même, et tu épuiseras ce peuple ; la chose est au-dessus de tes forces.'),
('n4m4', 16, 'Riches et influents', 'Exode 18.21 demande des hommes capables, craignant Dieu, intègres, ennemis de la cupidité ; la richesse n’est pas un critère.'),
('n4m4', 17, 'Pour que personne ne puisse le blâmer et pour agir bien devant Dieu et devant les hommes', '2 Corinthiens 8.20-21 : afin que personne ne nous blâme… car nous recherchons ce qui est bien, non seulement devant le Seigneur, mais aussi devant les hommes.'),
('n4m4', 18, 'La Parole de Dieu se répandait de plus en plus', 'Actes 6.7 : La parole de Dieu se répandait de plus en plus, et le nombre des disciples augmentait beaucoup à Jérusalem.'),
('n4m4', 19, 'Faire compter l’argent par au moins deux personnes, le noter et le déposer sur un compte de l’église', 'Comme Paul en 2 Corinthiens 8, la gestion à plusieurs et la trace écrite protègent tout le monde et honorent Dieu (1 Corinthiens 14.40 ; Luc 16.10).'),
('n4m4', 20, 'Un esclave de Philémon qui s’était enfui', 'Onésime était l’esclave de Philémon ; Paul écrit qu’il lui « a été inutile » autrefois et qu’il « a été séparé » de lui pour un temps (Philémon 11, 15-16).'),
('n4m4', 21, 'Pour que son bienfait ne soit pas comme forcé, mais volontaire', '« Je n’ai rien voulu faire sans ton avis, afin que ton bienfait ne soit pas comme forcé, mais qu’il soit volontaire » (Philémon 14).'),
('n4m4', 22, 'Comme un frère bien-aimé, comme Paul lui-même', '« Non plus comme un esclave, mais comme supérieur à un esclave, comme un frère bien-aimé… reçois-le comme moi-même » (Philémon 16-17).'),
('n4m4', 23, 'De les mettre sur son propre compte : « je paierai »', '« S’il t’a fait quelque tort, ou s’il te doit quelque chose, mets-le sur mon compte. Moi Paul, je l’écris de ma propre main, je paierai » (Philémon 18-19).'),
('n4m4', 24, 'De se paître eux-mêmes au lieu de paître le troupeau', '« Malheur aux pasteurs d’Israël, qui se paissaient eux-mêmes ! Les pasteurs ne devaient-ils pas paître le troupeau ? » (Ézéchiel 34.2).'),
('n4m4', 25, 'Que l’esprit soit sauvé au jour du Seigneur Jésus', '« Qu’un tel homme soit livré à Satan pour la destruction de la chair, afin que l’esprit soit sauvé au jour du Seigneur Jésus » (1 Corinthiens 5.5).'),
('n4m4', 26, 'Lui pardonner et le consoler, de peur qu’il ne soit accablé par une tristesse excessive', '« Vous devez bien plutôt lui pardonner et le consoler, de peur qu’il ne soit accablé par une tristesse excessive » (2 Corinthiens 2.7).'),
('n4m4', 27, 'Remettre en état, comme on répare un filet ou remet en place un membre démis', 'Katartizō signifie réparer, remettre en état : la discipline vise la restauration (Galates 6.1).')
